BucketedRoleManagement = {
	init: async function (app, container, bucket) {
		this.bucket = bucket;
		app = app || session.app;
		container = container || $(".component[name=BucketedRoleManagement]");
		if(!bucket) { return; }
		api.addToMetaCache([
			{
				"Name": "B2B",
				"Types": [
					[meta[B2B/B2BRole]]
				]
			}
		]);
		BucketedRoleManagement.setupRoleGrid(container, app, bucket);
	},

	setupRoleGrid: async function (container, app, bucket) {
		var config = { endpoint: "B2B/B2BRole", odataAppend: "?$filter=Buckets/any(r:r/BucketId eq " + bucket.Id + ")&$orderby=Name asc" };
		var ds = await model.getDatasource(config);
		var roleGrid = new GridWidget(container, ds);
		roleGrid.groupable = false;
		roleGrid.editable = false;
		roleGrid.toolbar = "<button name='createRole'><span class='k-icon k-i-plus'></span>[resource_displayname[NewRole]]</button>";
		roleGrid.columns = [{ field: "Name", title: "[resource_shortdisplayname[Name]]" }];
		roleGrid.commands.push({ name: "[resource_displayname[save]]", icon: 'k-i-save', text: "[resource_displayname[save]]" });
		roleGrid.commands.push({ name: "[resource_displayname[destroy]]", icon: 'k-i-delete', text: "[resource_displayname[delete]]" });
		roleGrid.detailTemplate = $("[name=roleDetails]").html();
		roleGrid.detailExpand = function (e) { BucketedRoleManagement.expandRole(e, app, roleGrid.kendoObject, bucket); };
		roleGrid.dataBound = function () {
			$("a[name=save]", roleGrid.gridElement).on("click", async (e) => await BucketedRoleManagement.save(e, roleGrid.kendoObject));
			$("a[name=destroy]", roleGrid.gridElement).off("click").on("click", async (e) => await BucketedRoleManagement.destroy(e, roleGrid.kendoObject, bucket));
		};
		await roleGrid.init();
		$("button[name=createRole]", roleGrid.gridElement).off("click").on("click", (e) => BucketedRoleManagement.createRole(bucket, roleGrid)); 
	},

	save: async function (e, grid) {
		e.preventDefault();
		var role = grid.dataItem($(e.currentTarget).closest("tr"));
		await role.save().then(() => { 
			notification.success("[resource_displayname[saved]]"); 
			grid.refresh();
		}).catch((err) => {  error(err); });
	},

	destroy: async function (e, grid, bucket) {
		e.preventDefault();
		var row = $(e.currentTarget).closest("tr");
		var role = grid.dataItem(row);
		grid.dataSource.remove(role);
		await api.destroy("B2B/BucketRole(BucketId=" + bucket.Id + ",RoleId=" + role.Id + ")").then(() => { 
			notification.success("[resource_displayname[deleted]]"); 
			grid.refresh();
		}).catch((err) => { error(err); })
	},

	expandRole: async function (e, app, grid, container) {
		var role = grid.dataItem(e.masterRow);
		var container = $(e.detailRow);
		if($(container).find(".component").length === 0) {
			$("[name=tabs]", container).kendoTabStrip({ animation: { open: { effects: "fadeIn" } } });
			$("[name=users]", container).html($("[name=B2BRoleUserManagementComponent]").first().html());
			$("[name=privs]", container).html($("[name=B2BRolePrivManagementComponent]").first().html());
			B2BRoleUserManagement.init(app, $(".component[name=B2BRoleUserManagement]", container), role); 
			B2BRolePrivManagement.init(app, $(".component[name=B2BRolePrivManagement]", container), role); 
		}
	},

	createRole: function (bucket, grid) {
		var newRole = {
			Id: "00000000-0000-0000-0000-000000000000",
			Name: "",
			Description: "",
			Buckets: [{BucketId: bucket.Id}],
			CreatedOn: (new Date()).toISOString(),
			LastUpdated: (new Date()).toISOString(),
			UsersArePortalAdmins: false,
			Privileges: ["bucket_read", "b2brole_read","b2buserrole_read", "b2buserrole_create", "b2buserrole_delete"]
		};
		var args = {
			fields: [{ field: "Name", title: "[resource_displayname[name]]" }, { field: "Description", title: "[resource_displayname[description]]" }],
			title: "[resource_displayname[newRole]]",
			data: newRole,
			confirm: "[resource_displayname[confirm]]",
			close: "[resource_displayname[close]]"
		};
		var addRoleDialog = new EditorDialog(args);
		addRoleDialog.events.confirm = async function () {
			newRole = addRoleDialog.data;
			await api.add("B2B/B2BRole", newRole).then(() => {
				notification.success("[resource_displayname[created]]");
				grid.refresh();
				addRoleDialog.events.close();
			}).catch((err) => error(err));
		};
		addRoleDialog.init();
	}
}
